from pathlib import Path
import gzip,hashlib,json,tarfile,collections
ROOT=Path.cwd();OUT=ROOT/'bench/results/2026-11-03/strided-stores';HERE=ROOT/'build/stride-hills/reviews/archive-audit'
def sha_bytes(b):return hashlib.sha256(b).hexdigest()
def load(p):return json.loads(Path(p).read_bytes())
index=json.loads(gzip.decompress((OUT/'archives.json.gz').read_bytes()));retention=load(OUT/'retention.json')
assert sha_bytes((OUT/'archives.json.gz').read_bytes())=='7e62809614a2da5d0350c329804e5ecb021a29788c6fb8f3d0ba86020243d2cd'
assert sha_bytes((OUT/'retention.json').read_bytes())=='8cbd42cdb5c5ceddd36caa12818b54fa99f1ad32769678de4c63db2691c65a84'
assert len(index['aliases'])==137511 and len(index['omitted'])==92 and len(index['documents'])==35
assert len(index['source_stages'])==6 and len(index['controls'])==7
assert len(index['required_guests'])==4298 and len(index['guests'])==4493 and len(index['engine_cache_files'])==678
assert index['storage']['prior_aliases_imported']==index['storage']['prior_documents_opened']==0
wanted={};by_path=collections.defaultdict(dict)
def want(location):wanted[(location['archive'],location['member'])]=location
for alias,location in index['aliases'].items():
 p,sep,h=alias.rpartition('@');assert sep and h==location['sha256']
 assert index['archives'][location['archive']]['members'][location['member']]=={'sha256':h,'bytes':location['bytes']}
 by_path[p][h]=location
for collection in ['source_stages','controls','host_stages']:
 def walk(x):
  if isinstance(x,dict):
   if {'archive','member','sha256','bytes'}<=x.keys():want(x)
   else:
    for v in x.values():walk(v)
  elif isinstance(x,list):
   for v in x:walk(v)
 walk(index[collection])
for location in index['public_bindings'].values():want(location)
for path,location in index['aliases'].items():
 original=path.rpartition('@')[0]
 if '/build/stride-hills/' in original and any(s in original for s in ['/reviews/','/qualification/preparation-history/','/delivery-preparation/import-shadow-1/']):
  want(location)
# Source snapshots and reviewer evidence are independently reconstructed from bytes,
# without reading prior report indexes or running packaged helper code.
payloads={};streamed_archives={}
for archive in sorted({a for a,m in wanted}):
 expected={m:loc for (a,m),loc in wanted.items() if a==archive}; found=set()
 with tarfile.open((OUT/archive).resolve(),'r|gz') as stream:
  for member in stream:
   assert member.isfile() and not member.name.startswith('/') and '..' not in Path(member.name).parts
   if member.name not in expected:continue
   assert member.name not in found;found.add(member.name)
   data=stream.extractfile(member).read();location=expected[member.name]
   assert len(data)==location['bytes'] and sha_bytes(data)==location['sha256']
   payloads[location['sha256']]=data
 assert found==set(expected)
 streamed_archives[archive]=len(found)
def read(location):return payloads[location['sha256']]
def readjson(location):return json.loads(read(location))
source_counts={}
for name,stage in index['source_stages'].items():
 source=readjson(stage['source']);tool=readjson(stage['toolchain'])
 assert source['headers']==tool['headers']=={n:v['sha256'] for n,v in stage['headers'].items()}
 assert source['patches']==tool['patches']=={n:v['sha256'] for n,v in stage['patches'].items()}
 assert stage['compiler_sha256']==tool['compiler_sha256']
 source_counts[name]={'headers':len(source['headers']),'patches':len(source['patches']),'compiler_sha256':stage['compiler_sha256']}
final=index['source_stages']['final'];fheaders={n:read(v) for n,v in final['headers'].items()}
expected_entries={
 'scan-control':('direct_wasm_scan.h','inline bool Function::ByteScan(While *loop) {\n','    return false;\n'),
 'stride-control':('direct_wasm_stride.h','inline bool Function::GroupedStores(While *loop) {\n','    return false;\n'),
 'merge-control':('direct_wasm_merge.h','inline bool Function::BoundedMerge(While *loop) {\n','    return false;\n'),
 'resource-control':('direct_wasm_temps.h','inline bool Function::ResourceFreeBlock(Block *block) {\n','    return false;\n'),
 'named-control':('direct_wasm_funvals.h','    if (!tail->fvbody) {\n','        return nullptr;\n'),
 'private-control':('direct_wasm_emit.h','inline void Compiler::AnalyzePrivateSnapshots() {\n','    return;\n'),
 'stencil-control':('direct_wasm_stencil.h','inline bool Function::ByteStencilLoop(ForLoop *loop, const Slot &binding, TypeExpr *ct, uint32_t lo, uint32_t hi) {\n','    return false;\n')}
assert set(expected_entries)==set(index['controls'])
for name,control in index['controls'].items():
 header,marker,insert=expected_entries[name];src=fheaders[header].decode();assert src.count(marker)==1
 for n,v in control['headers'].items():
  expected=fheaders[n]
  if n==header:expected=src.replace(marker,marker+insert,1).encode()
  assert read(v)==expected,(name,n)
 proof=readjson(control['match']);assert proof['status']=='matched' and proof['selected_compiler_sha256']==final['compiler_sha256']
 assert proof['selected_cmake']==proof['control_cmake'] and proof['header_count']==36 and proof['patch_count']==2
review_pins=0
for origin,location in index['aliases'].items():
 path=origin.rpartition('@')[0]
 if not path.startswith(str(ROOT/'build/stride-hills/reviews')) or not path.endswith('.json'):continue
 try:value=json.loads(read(location))
 except KeyError:continue
 def pins(x):
  global review_pins
  if isinstance(x,dict):
   if 'path' in x and 'sha256' in x and isinstance(x['path'],str):
    p=x['path'];h=x['sha256']
    variants=[p,str(ROOT/p)]
    assert any(h in by_path.get(v,{}) or v+'@'+h in index['omitted'] for v in variants),(path,p,h)
    review_pins+=1
   for v in x.values():pins(v)
  elif isinstance(x,list):
   for v in x:pins(v)
 pins(value)
for p,loc in index['public_bindings'].items():assert read(loc)==(ROOT/p).read_bytes(),p
public_review=OUT/'final-public-review.json';h=sha_bytes(public_review.read_bytes())
assert h=='b02514f76c552ca4e69066b9f812451acc1769fac864198c70b2ffde9ea2eb80'
assert read(by_path[str(ROOT/'build/stride-hills/reviews/final-public-review.json')][h])==public_review.read_bytes()
# No measured guests are hidden among explicit tool/SDK omissions.
for row in index['omitted'].values():
 assert row['reason'] and row['sha256'] not in index['required_guests']
 assert Path(row['original']).suffix not in ('.wasm','.cwasm','.bin')
for record in index['archives'].values():
 for member in record['members']:
  assert Path(member).suffix not in ('.a','.so','.xz'),member
# Failed setup remains separate; success cannot be inferred from its metadata.
assert any('/delivery-preparation/import-shadow-1/' in p for p in by_path)
assert any('/qualification/preparation-history/control-reuse-1/' in p for p in by_path)
assert all('attempt-2-full' not in n for n in index['source_stages'])
result={'status':'passed','source_stages':source_counts,'matched_controls_checked':7,
 'controls_are_exact_single_predicate_disables':True,'streamed_payload_locations':len(wanted),
 'streamed_archives':streamed_archives,'manual_review_pin_edges_checked':review_pins,
 'current_public_bindings_checked':len(index['public_bindings']),
 'omissions_checked':92,'measured_guest_omissions':0,'sdk_or_tool_binary_scope_leak':False,
 'prior_index_or_report_reads':0,'product_or_engine_execution':False}
(HERE/'independent-closure.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(result,indent=2))
